//!
//! The [`Container`] trait unifies the various `contains`/`contains_key` methods found on the
//! standard library collections behind a single interface. This is primarily useful for writing
//! generic helpers (such as test assertions) that need to check membership without caring about
//! the concrete container type.

use std::collections::{BTreeMap, BTreeSet, HashMap, HashSet, LinkedList, VecDeque};
use std::hash::{BuildHasher, Hash};
use std::ops::{Range, RangeFrom, RangeInclusive, RangeTo, RangeToInclusive};

/// A minimal abstraction for membership checks across container-like types.
///
/// The associated [`Item`](Container::Item) type is the element that membership is checked
/// against. For maps this is the key type, for sequences and sets it is the element type, and for
/// strings it is [`str`].
///
/// # Examples
///
/// ```
/// use nu_utils::container::Container;
///
/// assert!("hello world".contains("world"));
/// assert!(vec![1, 2, 3].contains(&2));
/// ```
pub trait Container {
    /// The element type that membership is checked against.
    type Item: ?Sized;

    /// Returns `true` if the container contains the given item.
    fn contains(&self, item: &Self::Item) -> bool;
}

impl Container for str {
    type Item = str;

    fn contains(&self, item: &Self::Item) -> bool {
        str::contains(self, item)
    }
}

impl Container for String {
    type Item = str;

    fn contains(&self, item: &Self::Item) -> bool {
        str::contains(self, item)
    }
}

impl<T: PartialEq, const N: usize> Container for [T; N] {
    type Item = T;

    fn contains(&self, item: &Self::Item) -> bool {
        self.iter().any(|x| x == item)
    }
}

impl<T: PartialEq> Container for [T] {
    type Item = T;

    fn contains(&self, item: &Self::Item) -> bool {
        <[T]>::contains(self, item)
    }
}

impl<T: PartialEq> Container for Vec<T> {
    type Item = T;

